1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Calculator</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0; min-height: 100vh; display: flex; align-items: center; justify-content: center;
11	    background: #eceef1; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
12	  }
13	  .calc {
14	    width: min(320px, 100vw - 32px); padding: 16px; border-radius: 20px;
15	    background: #1f2227; box-shadow: 0 12px 32px rgba(0,0,0,.25);
16	  }
17	  .display {
18	    height: 80px; margin-bottom: 16px; padding: 0 12px; border-radius: 12px;
19	    background: #2b2f36; color: #fff; font-size: 40px; text-align: right;
20	    line-height: 80px; overflow: hidden; white-space: nowrap; text-overflow: ellipsis;
21	  }
22	  .keys { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; }
23	  button {
24	    height: 60px; border: 0; border-radius: 12px; font-size: 22px; cursor: pointer;
25	    background: #3a3f47; color: #fff;
26	  }
27	  button:active { filter: brightness(1.25); }
28	  .op { background: #f59e0b; }
29	  .clear { background: #9ca3af; color: #111; }
30	  .wide { grid-column: span 2; }
31	  .tape { margin-top: 16px; border-radius: 12px; background: #2b2f36; color: #fff; }
32	  .tape-head {
33	    display: flex; align-items: center; justify-content: space-between; padding: 8px 12px;
34	    font-size: 13px; color: #9ca3af;
35	  }
36	  .tape-clear { height: auto; padding: 4px 10px; font-size: 13px; border-radius: 8px; }
37	  .tape-list { max-height: 180px; overflow-y: auto; }
38	  .tape-row { padding: 6px 12px; border-top: 1px solid #3a3f47; text-align: right; }
39	  .tape-expr { font-size: 13px; color: #9ca3af; overflow-wrap: anywhere; }
40	  .tape-result { font-size: 20px; }
41	</style>
42	</head>
43	<body>
44	<div class="calc">
45	  <div class="display" data-testid="calc-display" data-value="0" data-error="false">0</div>
46	  <div class="keys">
47	    <button class="clear wide" data-testid="key-clear">AC</button>
48	    <button class="clear" data-testid="key-sign">±</button>
49	    <button class="op" data-testid="key-div" data-op="/">÷</button>
50	    <button class="clear wide" data-testid="key-lparen">(</button>
51	    <button class="clear wide" data-testid="key-rparen">)</button>
52	    <button data-testid="key-7" data-digit="7">7</button>
53	    <button data-testid="key-8" data-digit="8">8</button>
54	    <button data-testid="key-9" data-digit="9">9</button>
55	    <button class="op" data-testid="key-mul" data-op="*">×</button>
56	    <button data-testid="key-4" data-digit="4">4</button>
57	    <button data-testid="key-5" data-digit="5">5</button>
58	    <button data-testid="key-6" data-digit="6">6</button>
59	    <button class="op" data-testid="key-sub" data-op="-">−</button>
60	    <button data-testid="key-1" data-digit="1">1</button>
61	    <button data-testid="key-2" data-digit="2">2</button>
62	    <button data-testid="key-3" data-digit="3">3</button>
63	    <button class="op" data-testid="key-add" data-op="+">+</button>
64	    <button class="wide" data-testid="key-0" data-digit="0">0</button>
65	    <button data-testid="key-dot">.</button>
66	    <button class="op" data-testid="key-equals">=</button>
67	  </div>
68	  <div class="tape" data-testid="calc-tape">
69	    <div class="tape-head">
70	      <span>History</span>
71	      <button class="tape-clear" data-testid="tape-clear">Clear</button>
72	    </div>
73	    <div class="tape-list"></div>
74	  </div>
75	</div>
76	<script>
77	  var entry = "0";      // text of the current entry or last result
78	  var stored = null;    // left operand
79	  var op = null;        // pending operator
80	  var fresh = true;     // next digit starts a new entry
81	  var waiting = false;  // an operator was just pressed and has no right operand yet
82	  var error = false;    // set by a non-finite result; only clear leaves it
83	  var groups = [];      // outer {stored, op} saved by each open parenthesis
84	  var parts = [];       // expression text of the current group, for the tape
85	  var partGroups = [];  // outer parts saved by each open parenthesis
86	  var operandText = null; // text of a just-closed group, standing in for the entry
87	  var SYMBOLS = { "+": "+", "-": "\u2212", "*": "\u00d7", "/": "\u00f7" };
88	
89	  var display = document.querySelector('[data-testid="calc-display"]');
90	  var tapeList = document.querySelector(".tape-list");
91	
92	  // Text of the current right operand as it belongs in the expression.
93	  function operandString() {
94	    if (operandText !== null) return operandText;
95	    return fresh ? format(Number(entry)) : entry.replace(/\.$/, "");
96	  }
97	
98	  function addTapeRow(expr, value) {
99	    var row = document.createElement("div");
100	    row.className = "tape-row";
101	    row.setAttribute("data-testid", "tape-row");
102	    var e = document.createElement("div");
103	    e.className = "tape-expr";
104	    e.setAttribute("data-testid", "tape-expr");
105	    e.textContent = expr;
106	    var r = document.createElement("div");
107	    r.className = "tape-result";
108	    r.setAttribute("data-testid", "tape-result");
109	    r.setAttribute("data-value", String(value));
110	    r.textContent = format(value);
111	    row.appendChild(e);
112	    row.appendChild(r);
113	    tapeList.insertBefore(row, tapeList.firstChild);
114	  }
115	
116	  function compute(a, b, o) {
117	    if (o === "+") return a + b;
118	    if (o === "-") return a - b;
119	    if (o === "*") return a * b;
120	    return a / b;
121	  }
122	
123	  // Presentation only: at most 10 significant digits, no trailing zeros,
124	  // exponential below 1e-9 or from 1e10. Stored values are never rounded.
125	  function format(v) {
126	    if (v === 0) return "0";
127	    var r = Number(v.toPrecision(10));
128	    var a = Math.abs(r);
129	    if (a >= 1e10 || a < 1e-9) return r.toExponential();
130	    var e = Math.floor(Math.log10(a));
131	    if (Math.pow(10, e) > a) e--;
132	    var s = r.toFixed(Math.max(0, 9 - e));
133	    return s.indexOf(".") === -1 ? s : s.replace(/0+$/, "").replace(/\.$/, "");
134	  }
135	
136	  // While typing, the entry shows exactly as typed; results are formatted.
137	  function render() {
138	    display.textContent = error ? "Error" : fresh ? format(Number(entry)) : entry;
139	    display.setAttribute("data-value", String(Number(entry)));
140	    display.setAttribute("data-error", String(error));
141	  }
142	
143	  function digit(d) {
144	    if (fresh) { entry = d; fresh = false; }
145	    else entry = entry === "0" || entry === "-0" ? entry.slice(0, -1) + d : entry + d;
146	    waiting = false;
147	    operandText = null;
148	  }
149	
150	  function dot() {
151	    if (fresh) { entry = "0."; fresh = false; }
152	    else if (entry.indexOf(".") === -1) entry += ".";
153	    waiting = false;
154	    operandText = null;
155	  }
156	
157	  // Acts on the current entry. A typed entry keeps its text; a result is negated as a value.
158	  function sign() {
159	    if (!fresh) entry = entry.charAt(0) === "-" ? entry.slice(1) : "-" + entry;
160	    else entry = String(-Number(entry));
161	    waiting = false;
162	    operandText = null;
163	  }
164	
165	  // Immediate execution: each operator finishes the waiting operation, strictly
166	  // left to right, no precedence. 2 + 3 × 4 = is 20. The display always shows a real result.
167	  function operator(o) {
168	    if (waiting) parts[parts.length - 1] = SYMBOLS[o];
169	    else parts.push(operandString(), SYMBOLS[o]);
170	    operandText = null;
171	    if (op !== null && !waiting) finish(compute(stored, Number(entry), op));
172	    stored = Number(entry);
173	    op = o;
174	    fresh = true;
175	    waiting = true;
176	  }
177	
178	  // Division by zero (or any non-finite result) enters the error state.
179	  function finish(result) {
180	    entry = String(result);
181	    if (!isFinite(result)) error = true;
182	  }
183	
184	  // A group saves the outer operation and starts a fresh one inside.
185	  // Inside a group the same left-to-right rule applies.
186	  function lparen() {
187	    partGroups.push(parts);
188	    parts = []; operandText = null;
189	    groups.push({ stored: stored, op: op });
190	    entry = "0"; stored = null; op = null; fresh = true; waiting = false;
191	  }
192	
193	  // Closing finishes the inner operation; its result becomes the outer right operand.
194	  function rparen() {
195	    if (groups.length === 0) return;
196	    if (waiting) parts.pop();
197	    else parts.push(operandString());
198	    var inner = "(" + parts.join(" ") + ")";
199	    parts = partGroups.pop();
200	    operandText = inner;
201	    if (op !== null && !waiting) finish(compute(stored, Number(entry), op));
202	    var g = groups.pop();
203	    stored = g.stored;
204	    op = g.op;
205	    fresh = true;
206	    waiting = false;
207	  }
208	
209	  // Equals closes any open groups first.
210	  function equals() {
211	    while (groups.length && !error) rparen();
212	    if (op === null || error) return;
213	    parts.push(operandString());
214	    finish(compute(stored, Number(entry), op));
215	    if (!error) addTapeRow(parts.join(" "), Number(entry));
216	    parts = []; operandText = null;
217	    stored = null;
218	    op = null;
219	    fresh = true;
220	    waiting = false;
221	  }
222	
223	  function clear() {
224	    entry = "0"; stored = null; op = null; fresh = true; waiting = false; error = false; groups = [];
225	    parts = []; partGroups = []; operandText = null;
226	  }
227	
228	  document.querySelector(".keys").addEventListener("click", function (e) {
229	    var b = e.target.closest("button");
230	    if (!b) return;
231	    var id = b.getAttribute("data-testid");
232	    if (error && id !== "key-clear") return;
233	    if (b.hasAttribute("data-digit")) digit(b.getAttribute("data-digit"));
234	    else if (b.hasAttribute("data-op")) operator(b.getAttribute("data-op"));
235	    else if (id === "key-dot") dot();
236	    else if (id === "key-sign") sign();
237	    else if (id === "key-lparen") lparen();
238	    else if (id === "key-rparen") rparen();
239	    else if (id === "key-equals") equals();
240	    else if (id === "key-clear") clear();
241	    render();
242	  });
243	
244	  // Clearing the tape leaves the calculator untouched.
245	  document.querySelector('[data-testid="tape-clear"]').addEventListener("click", function () {
246	    tapeList.textContent = "";
247	  });
248	
249	  render();
250	</script>
251	</body>
252	</html>
